import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public final class ClaimQuery {

    public record Claim(String id, String policyNumber, String status, BigDecimal amount, LocalDate incidentDate) {
    }

    private ClaimQuery() {
    }

    public static List<Claim> filter(List<Claim> claims, String status, BigDecimal minAmount, LocalDate from, LocalDate to) {
        if (claims == null) {
            return List.of();
        }
        List<Claim> result = new ArrayList<>();
        for (Claim claim : claims) {
            if (claim == null) {
                continue;
            }
            if (status != null && !claim.status().equalsIgnoreCase(status)) {
                continue;
            }
            if (minAmount != null && claim.amount().compareTo(minAmount) <= 0) {
                continue;
            }
            if (from != null && claim.incidentDate().isBefore(from)) {
                continue;
            }
            if (to != null && claim.incidentDate().isAfter(to)) {
                continue;
            }
            result.add(claim);
        }
        return result;
    }
}

