public final class ClaimQuery {

    public record Claim(String id, String policyNumber, String status, BigDecimal amount, LocalDate incidentDate) {
    }

    private ClaimQuery() {
    }

    public static List<Claim> filter(List<Claim> claims, String status, BigDecimal minAmount, LocalDate from, LocalDate to) {
        if (claims == null) {
            return List.of();
        }
        String wanted = status == null ? "" : status.trim();
        boolean filterStatus = !wanted.isEmpty() && !wanted.equalsIgnoreCase("ANY");
        List<Claim> result = new ArrayList<>();
        for (Claim claim : claims) {
            if (claim == null) {
                continue;
            }
            if (filterStatus) {
                if (claim.status() == null || !claim.status().trim().equalsIgnoreCase(wanted)) {
                    continue;
                }
            }
            if (minAmount != null) {
                if (claim.amount() == null || claim.amount().compareTo(minAmount) < 0) {
                    continue;
                }
            }
            if (from != null) {
                if (claim.incidentDate() == null || claim.incidentDate().isBefore(from)) {
                    continue;
                }
            }
            if (to != null) {
                if (claim.incidentDate() == null || claim.incidentDate().isAfter(to)) {
                    continue;
                }
            }
            result.add(claim);
        }
        result.sort(Comparator
                .comparing(Claim::incidentDate, Comparator.nullsLast(Comparator.reverseOrder()))
                .thenComparing(claim -> claim.id() == null ? "" : claim.id()));
        return result;
    }

    public record Summary(int count, BigDecimal total, BigDecimal max, java.util.Map<String, Integer> byStatus) {
    }

    public static Summary summarize(List<Claim> claims) {
        if (claims == null) {
            return new Summary(0, BigDecimal.ZERO, BigDecimal.ZERO, java.util.Map.of());
        }
        int count = 0;
        BigDecimal total = BigDecimal.ZERO;
        BigDecimal max = null;
        java.util.Map<String, Integer> byStatus = new java.util.TreeMap<>();
        for (Claim claim : claims) {
            if (claim == null) {
                continue;
            }
            count += 1;
            if (claim.amount() != null) {
                total = total.add(claim.amount());
                if (max == null || claim.amount().compareTo(max) > 0) {
                    max = claim.amount();
                }
            }
            String key = claim.status() == null || claim.status().trim().isEmpty()
                    ? "UNKNOWN" : claim.status().trim().toUpperCase();
            byStatus.merge(key, 1, Integer::sum);
        }
        return new Summary(count, total, max == null ? BigDecimal.ZERO : max, byStatus);
    }
}
